import {
  Archive, ArrowRight, BadgeCheck, BookDown, BookOpen, CircleHelp, FileImage, Inbox, LayoutDashboard, MessageCircle, Route,
  ChevronDown, Menu, PackagePlus, Pencil, Plus, RefreshCw, Save, Search, Settings, SlidersHorizontal,
  Upload, Globe2, Palette, LayoutTemplate, Footprints, X, LogOut, Trash2, Bell, UserRound
} from "lucide-react";
